/*
 * The game's own `.data`: 666 objects in 60,588 bytes.
 *
 * Covers rom 0x03E040..0x04CCEC (vram 0x8006A840..0x800794EC) -- everything
 * between libsn/SNMAIN's module descriptor and libspu's data, which is to say
 * every byte of `.data` the game itself contributes. It is the last unowned
 * region of this executable apart from 968 bytes of zero above `_gp` that no
 * C definition can emit.
 *
 *
 * WHY THIS IS A UNIT OF ITS OWN, AND WHY THAT IS NOT A CLAIM
 *
 * The region is really the `.data` of the ~43 original translation units that
 * make up the game, laid out in link order, one contiguous run each. This file
 * is not a claim that it was one unit. It is the shape the evidence supports,
 * and it is the third time this container has reached for it --
 * `csrc/game_gp.c` and `csrc/gp_data.c` are the other two, and the first of
 * them carries the proof that our 38 `c` subsegments are NOT the original
 * units.
 *
 * The signal that would place these objects per unit was measured and is not
 * enough. Two parts:
 *
 * 1. **Reference.** Of the 666 objects, 127 are mentioned by exactly one of
 *    the 38 units, and 116 of those 127 fit a monotone link-order assignment
 *    -- against a null whose maximum over 2,000 shuffles is 76, so the signal
 *    is real. But use is not ownership, and eight of the eleven exceptions
 *    are `unk_72A8`, which is 305 functions and an addressing-mode carve.
 *    docs/data-map.md has the measurement.
 * 2. **`$gp` membership**, which would fix the carve the reference signal
 *    needs. `tools/tuscan.py --source objects --cores` reads it out of our
 *    own objects now, and reports 67 of 1053 functions making a
 *    `$gp`-relative access at all, 29 proven cores covering 8.5% of the
 *    block, and boundary windows up to 170 functions wide. That is not a
 *    carve.
 *
 * A data-only unit is also FORCED, not merely preferred. Defining a small
 * object of this region inside one of the `-G8` units would make its size
 * known to cc1psx, and a `.extern` of 8 bytes or fewer at `-G8` asks gas for
 * a GPREL16 -- which cannot reach, because this region starts 0x16154 below
 * `_gp` and GPREL16 spans +/-32K.
 *
 * When a real carve exists, these definitions move into it and this file goes
 * away. Nothing here is load-bearing for that except the addresses.
 *
 *
 * HOW IT IS SHAPED, AND WHAT EACH RULE COST
 *
 * `-G0`, through an exact-target Makefile override, so every object lands in
 * `.data` whatever its size. ONE OBJECT PER `dlabel`, sized to its span --
 * and here that is checkable rather than assumed: the listing's emitted bytes
 * equal the span for all 666. The 666 become 668 C objects because two
 * `dlabel`s mix element widths (`D_8006A840` is a word then three bytes,
 * `D_8006A847` is a byte then a word) and one C object cannot; the extra
 * pieces take invented `D_` names. NO ARRAY MAY START AT A NON-4-ALIGNED
 * ADDRESS -- gcc 2.7.2's `DATA_ALIGNMENT` forces every array to 4 and
 * `__attribute__((aligned(1)))` does not lower it -- so the three objects at
 * odd addresses (`D_8006A847`, `D_8007382A`, `D_8007382B`) are scalars.
 *
 * Three `dlabel`s are NOT strings even though spimdisasm guessed `.asciz` for
 * them: `D_80078214`, `D_80078238` and `D_8007825C` are the four bytes
 * `40 2C 20 00` and friends inside a run of GPU primitive words, and they are
 * written here as the words they are.
 *
 *
 * THE 1,072 RELOCATIONS
 *
 * 142 objects carry a symbol operand and the file names 852 distinct symbols
 * -- 453 of its own objects, 194 elsewhere in the image, 130 functions, and
 * the nineteen `STR_NAME_*` of csrc/str/names.c, which a pointer table here
 * indexes. Every one was checked against the listing mechanically rather than
 * by sampling: the 1,072 (address, symbol) pairs `dataverify.py` reports and
 * the 1,072 in `asm/data/game_data.data.s` are the same set, with no address
 * in one and not the other and no symbol disagreeing. That matters because a
 * relocated word is MASKED in the byte comparison, so it is the only check
 * those words get.
 *
 * A reference to one of this file's own scalars takes its address --
 * `(u32)&D_X`, not a cast of its value, which is docs/owning-data.md §8
 * rule 6. Arrays decay.
 *
 *
 * WHAT IS IN HERE
 *
 * Pointer and descriptor tables at the bottom; four COMPILED EVENT SCRIPTS
 * (`D_8006B230` at 6,684 bytes, `D_8006FFC8` at 3,756, `D_8006F5DC` at 2,540
 * and `D_80070E74` at 608) which are 87-92% full-width Shift-JIS by coverage
 * but are NOT string pools -- they interleave control bytes, the game's own
 * 0x08/0x11 script opcodes and six embedded 32-bit pointers, which is why
 * they stay word arrays and could not be split into strings even if something
 * pointed at the pieces, and nothing does; and from about 0x47000 a long run
 * of uniform fixed-size records with an 8-byte-entry directory at 0x4CC48.
 *
 *
 * VERIFYING A CHANGE
 *
 *     python3 tools/decomp/dataverify.py csrc/game_data.c --window game_data
 *
 * 668 objects, layout ok, bytes OK, `.data` 60,588, NEXT YAML BOUNDARY
 * 0x4ccec -- which is independently where libspu's data begins.
 */

